1	package brainstore
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"path/filepath"
10		"strings"
11		"time"
12	
13		clibase "github.com/entireio/entire-brain/internal/cli/internal/base"
14	)
15	
16	// HistoryDirName is the brain-relative directory holding the history
17	// projection and the session privacy state beside it.
18	const HistoryDirName = "history"
19	
20	const (
21		SessionTombstonesFileName = "tombstones.json"
22		SessionTombstonesPath     = HistoryDirName + "/" + SessionTombstonesFileName
23		SessionTombstonesVersion  = 1
24	)
25	
26	type SessionTombstones struct {
27		Version int `json:"version"`
28		// Excluded maps session_id -> tombstone. Content-free by design: a
29		// tombstone must never retain what it excludes.
30		Excluded map[string]SessionTombstone `json:"excluded"`
31	}
32	
33	type SessionTombstone struct {
34		At     time.Time `json:"at"`
35		Reason string    `json:"reason,omitempty"`
36	}
37	
38	type SessionTombstoneState string
39	
40	const (
41		SessionTombstoneAbsent      SessionTombstoneState = "absent"
42		SessionTombstoneCurrent     SessionTombstoneState = "current"
43		SessionTombstoneCorrupt     SessionTombstoneState = "corrupt"
44		SessionTombstoneUnsupported SessionTombstoneState = "unsupported"
45	)
46	
47	// SessionTombstoneFileState is content-free state for status and projection
48	// identity checks. Identity hashes the exact bytes parsed by the checked
49	// loader, avoiding a second-read race during generation preparation.
50	type SessionTombstoneFileState struct {
51		State    SessionTombstoneState
52		Version  int
53		Identity string
54	}
55	
56	// SessionTombstoneLoadError keeps privacy failures machine-classifiable on
57	// every serving and derivation boundary. Its Error prefix is also the
58	// repository's established JSON command-error contract.
59	type SessionTombstoneLoadError struct {
60		Code    string
61		State   SessionTombstoneState
62		Version int
63		Err     error
64	}
65	
66	func (e *SessionTombstoneLoadError) Error() string {
67		detail := "session tombstone state is invalid"
68		if e.Err != nil {
69			detail = e.Err.Error()
70		}
71		return e.Code + ": " + detail
72	}
73	
74	func (e *SessionTombstoneLoadError) Unwrap() error { return e.Err }
75	
76	func EmptySessionTombstones() SessionTombstones {
77		return SessionTombstones{Version: SessionTombstonesVersion, Excluded: map[string]SessionTombstone{}}
78	}
79	
80	// LoadSessionTombstonesChecked is the only loader allowed on serving,
81	// derivation, worker, privacy, and administration boundaries. Missing means a
82	// valid empty policy. Once the file exists, unreadable/malformed state fails
83	// closed: treating it as empty could disclose or re-derive excluded content.
84	func LoadSessionTombstonesChecked(brainDir string) (SessionTombstones, SessionTombstoneFileState, error) {
85		empty := EmptySessionTombstones()
86		data, present, err := ReadPrivacyArtifact(brainDir, SessionTombstonesPath, "session tombstones", clibase.MaxManifestBytes)
87		if err != nil {
88			state := SessionTombstoneFileState{State: SessionTombstoneCorrupt}
89			return SessionTombstones{}, state, &SessionTombstoneLoadError{
90				Code: StateCorruptCode, State: state.State,
91				Err: fmt.Errorf("read session tombstones: %w", err),
92			}
93		}
94		if !present {
95			return empty, SessionTombstoneFileState{State: SessionTombstoneAbsent, Version: SessionTombstonesVersion, Identity: "absent"}, nil
96		}
97		sum := sha256.Sum256(data)
98		state := SessionTombstoneFileState{Identity: "sha256:" + hex.EncodeToString(sum[:])}
99		var header struct {
100			Version int `json:"version"`
101		}
102		if err := json.Unmarshal(data, &header); err != nil {
103			state.State = SessionTombstoneCorrupt
104			return SessionTombstones{}, state, &SessionTombstoneLoadError{
105				Code: StateCorruptCode, State: state.State,
106				Err: errors.New("session tombstones cannot be parsed"),
107			}
108		}
109		state.Version = header.Version
110		if header.Version > SessionTombstonesVersion {
111			state.State = SessionTombstoneUnsupported
112			return SessionTombstones{}, state, &SessionTombstoneLoadError{
113				Code: UnsupportedVersionCode, State: state.State, Version: header.Version,
114				Err: fmt.Errorf("session tombstone schema %d is unsupported (current %d)", header.Version, SessionTombstonesVersion),
115			}
116		}
117		var stones SessionTombstones
118		if _, err := DecodeVersionedJSONBody(data, &stones, false); err != nil {
119			message := "session tombstones cannot be parsed strictly"
120			if errors.Is(err, ErrTrailingJSONData) {
121				message = "session tombstones contain trailing JSON data"
122			}
123			state.State = SessionTombstoneCorrupt
124			return SessionTombstones{}, state, &SessionTombstoneLoadError{
125				Code: StateCorruptCode, State: state.State,
126				Err: errors.New(message),
127			}
128		}
129		if stones.Version != SessionTombstonesVersion {
130			state.State = SessionTombstoneCorrupt
131			return SessionTombstones{}, state, &SessionTombstoneLoadError{
132				Code: StateCorruptCode, State: state.State, Version: stones.Version,
133				Err: fmt.Errorf("session tombstone schema %d is invalid (current %d)", stones.Version, SessionTombstonesVersion),
134			}
135		}
136		if stones.Excluded == nil {
137			state.State = SessionTombstoneCorrupt
138			return SessionTombstones{}, state, &SessionTombstoneLoadError{
139				Code: StateCorruptCode, State: state.State,
140				Err: errors.New("session tombstones excluded map is missing"),
141			}
142		}
143		state.State = SessionTombstoneCurrent
144		return stones, state, nil
145	}
146	
147	// LoadSessionTombstones is a convenience for tests and locked code that has
148	// already established a valid tombstone file. It panics instead of ever
149	// converting invalid present state into an empty policy. Production boundaries
150	// must use LoadSessionTombstonesChecked and return its typed error.
151	func LoadSessionTombstones(brainDir string) SessionTombstones {
152		stones, _, err := LoadSessionTombstonesChecked(brainDir)
153		if err != nil {
154			panic(err)
155		}
156		return stones
157	}
158	
159	func SaveSessionTombstones(brainDir string, stones SessionTombstones) error {
160		if _, _, err := LoadSessionTombstonesChecked(brainDir); err != nil {
161			return err
162		}
163		data, err := MarshalSessionTombstones(stones)
164		if err != nil {
165			return err
166		}
167		return WriteBrainRelativeFileAtomic(brainDir, SessionTombstonesPath, data, 0o600)
168	}
169	
170	func MarshalSessionTombstones(stones SessionTombstones) ([]byte, error) {
171		stones.Version = SessionTombstonesVersion
172		data, err := json.MarshalIndent(stones, "", "  ")
173		if err != nil {
174			return nil, err
175		}
176		return append(data, '\n'), nil
177	}
178	
179	// NormalizePrivacyTranscriptPath normalizes a transcript path for exclusion
180	// matching: trimmed, cleaned, and slash-separated; empty when nothing remains.
181	func NormalizePrivacyTranscriptPath(path string) string {
182		trimmed := strings.TrimSpace(path)
183		if trimmed == "" {
184			return ""
185		}
186		clean := filepath.Clean(filepath.FromSlash(trimmed))
187		if clean == "." {
188			return ""
189		}
190		return filepath.ToSlash(clean)
191	}
