1	package brainstore
2	
3	import "strings"
4	
5	// SessionReadGuard is the retrieval-time tombstone view: every
6	// conversation/history/fact retrieval boundary consults it so an excluded
7	// session becomes unreadable the moment its tombstone lands, without waiting
8	// for the derived rebuild. Defense in depth, not a substitute for cleanup.
9	type SessionReadGuard struct {
10		IDs            map[string]SessionTombstone
11		Paths          map[string]string // excluded transcript rel -> session id, from manifest and durable scope
12		PolicyIdentity string            // exact checked tombstone bytes used to build the guard
13	}
14	
15	// DurableExcludedTranscriptPaths extends paths with each excluded session's
16	// durable transaction scope so refresh cannot reopen or reindex an excluded
17	// export it no longer names. A nil paths map starts empty.
18	func DurableExcludedTranscriptPaths(brainDir string, stones SessionTombstones, paths map[string]string) (map[string]string, error) {
19		if paths == nil {
20			paths = map[string]string{}
21		}
22		for id := range stones.Excluded {
23			tx, _, err := LoadPrivacyTransactionChecked(brainDir, id)
24			if err != nil {
25				return nil, err
26			}
27			durable, err := PrivacyTransactionTranscriptPaths(tx)
28			if err != nil {
29				return nil, err
30			}
31			for _, rel := range durable {
32				paths[rel] = id
33			}
34		}
35		return paths, nil
36	}
37	
38	// LoadSessionReadGuard builds the guard from tombstones, durable transaction
39	// paths, and any additional excluded paths the caller resolves from its
40	// manifest (nil when there is none). Records that lost their session id still
41	// resolve by path. Invalid present state is a
42	// typed error; serving must stop rather than silently restore excluded data.
43	func LoadSessionReadGuard(brainDir string, manifestPaths func(SessionTombstones) map[string]string) (SessionReadGuard, error) {
44		stones, state, err := LoadSessionTombstonesChecked(brainDir)
45		if err != nil {
46			return SessionReadGuard{}, err
47		}
48		guard := SessionReadGuard{PolicyIdentity: state.Identity}
49		if len(stones.Excluded) == 0 {
50			return guard, nil
51		}
52		guard.IDs = stones.Excluded
53		seed := map[string]string{}
54		if manifestPaths != nil {
55			seed = manifestPaths(stones)
56		}
57		guard.Paths, err = DurableExcludedTranscriptPaths(brainDir, stones, seed)
58		if err != nil {
59			return SessionReadGuard{}, err
60		}
61		return guard, nil
62	}
63	
64	func (g SessionReadGuard) Empty() bool { return len(g.IDs) == 0 }
65	
66	func (g SessionReadGuard) BlocksSession(sessionID string) bool {
67		if g.Empty() {
68			return false
69		}
70		_, ok := g.IDs[strings.TrimSpace(sessionID)]
71		return ok
72	}
73	
74	// BlocksPath reports whether a transcript path belongs to an excluded session,
75	// matching under the shared privacy path normalization.
76	func (g SessionReadGuard) BlocksPath(path string) bool {
77		_, ok := g.Paths[NormalizePrivacyTranscriptPath(path)]
78		return ok
79	}
