1	package brainstore
2	
3	import (
4		"fmt"
5		"path/filepath"
6		"sort"
7	)
8	
9	// RetrievalPrivacyPolicy is the checked tombstone generation under which a
10	// response was assembled. Keeping the brain path beside the identity lets the
11	// same final writer cover single-repository, workspace, get, and brief output.
12	type RetrievalPrivacyPolicy struct {
13		BrainDir            string
14		Identity            string
15		RequireDerivedClean bool
16	}
17	
18	// CaptureRetrievalPrivacyPolicy records the checked tombstone identity for one
19	// Brain. Loading the full guard, not just the tombstone file, keeps capture
20	// failing on the same invalid durable-transaction state every read would.
21	func CaptureRetrievalPrivacyPolicy(brainDir string) (RetrievalPrivacyPolicy, error) {
22		guard, err := LoadSessionReadGuard(brainDir, nil)
23		if err != nil {
24			return RetrievalPrivacyPolicy{}, err
25		}
26		return RetrievalPrivacyPolicy{BrainDir: brainDir, Identity: guard.PolicyIdentity}, nil
27	}
28	
29	// RequireRetrievalPrivacyPolicyIdentity fails when the Brain's checked
30	// tombstone identity no longer matches the identity a response was assembled
31	// under.
32	func RequireRetrievalPrivacyPolicyIdentity(brainDir, expected string) error {
33		guard, err := LoadSessionReadGuard(brainDir, nil)
34		if err != nil {
35			return err
36		}
37		if guard.PolicyIdentity != expected {
38			return fmt.Errorf("%s: retrieval privacy policy changed during response assembly; retry the request", PrivacyDirtyCode)
39		}
40		return nil
41	}
42	
43	// WithLockedRetrievalPrivacyPolicies is the mutation-side policy boundary.
44	// Tombstone mutations use the same per-Brain write lock. Locks are acquired in
45	// deterministic path order so a workspace operation spanning several Brains
46	// cannot deadlock with another workspace operation containing the same members.
47	// requireDerivedClean is the caller's derived-read gate, enforced for every
48	// policy that demands it while the locks are held.
49	//
50	// Read-response emission does NOT use this: it validates without locks (see
51	// ValidateRetrievalPrivacyPolicies). Only operations that mutate pattern/corpus
52	// state under the captured policies still take the locks.
53	func WithLockedRetrievalPrivacyPolicies(policies []RetrievalPrivacyPolicy, requireDerivedClean func(string) error, fn func() error) error {
54		unlock, err := AcquireRetrievalPrivacyPolicies(policies, requireDerivedClean)
55		if err != nil {
56			return err
57		}
58		defer unlock()
59		return fn()
60	}
61	
62	// ValidateRetrievalPrivacyPolicies re-checks each policy identity and derived
63	// gate WITHOUT taking any lock. This is the read-response emission check: a
64	// response assembled under a policy that has since changed fails closed, but a
65	// tombstone landing after this check and before the output write is not
66	// blocked — it takes effect on the next command. That instant-suppression
67	// guarantee was deliberately retired: enforcing it meant acquiring the global
68	// brain write lock per response, so any long-running writer (promote, distill)
69	// failed every concurrent reader with brain_locked.
70	func ValidateRetrievalPrivacyPolicies(policies []RetrievalPrivacyPolicy, requireDerivedClean func(string) error) error {
71		byBrain, derivedClean, brainDirs, err := normalizeRetrievalPrivacyPolicies(policies)
72		if err != nil {
73			return err
74		}
75		return validateNormalizedRetrievalPolicies(byBrain, derivedClean, brainDirs, requireDerivedClean)
76	}
77	
78	func validateNormalizedRetrievalPolicies(byBrain map[string]string, derivedClean map[string]bool, brainDirs []string, requireDerivedClean func(string) error) error {
79		for _, brainDir := range brainDirs {
80			if err := RequireRetrievalPrivacyPolicyIdentity(brainDir, byBrain[brainDir]); err != nil {
81				return err
82			}
83			if derivedClean[brainDir] {
84				if err := requireDerivedClean(brainDir); err != nil {
85					return err
86				}
87			}
88		}
89		return nil
90	}
91	
92	func normalizeRetrievalPrivacyPolicies(policies []RetrievalPrivacyPolicy) (map[string]string, map[string]bool, []string, error) {
93		byBrain := make(map[string]string, len(policies))
94		derivedClean := make(map[string]bool, len(policies))
95		for _, policy := range policies {
96			if policy.BrainDir == "" {
97				continue
98			}
99			brainDir := filepath.Clean(policy.BrainDir)
100			if prior, exists := byBrain[brainDir]; exists && prior != policy.Identity {
101				return nil, nil, nil, fmt.Errorf("%s: response was assembled under conflicting privacy policies", PrivacyDirtyCode)
102			}
103			byBrain[brainDir] = policy.Identity
104			derivedClean[brainDir] = derivedClean[brainDir] || policy.RequireDerivedClean
105		}
106		brainDirs := make([]string, 0, len(byBrain))
107		for brainDir := range byBrain {
108			brainDirs = append(brainDirs, brainDir)
109		}
110		sort.Strings(brainDirs)
111		return byBrain, derivedClean, brainDirs, nil
112	}
113	
114	func AcquireRetrievalPrivacyPolicies(policies []RetrievalPrivacyPolicy, requireDerivedClean func(string) error) (func(), error) {
115		byBrain, derivedClean, brainDirs, err := normalizeRetrievalPrivacyPolicies(policies)
116		if err != nil {
117			return nil, err
118		}
119		unlocks := make([]func(), 0, len(brainDirs))
120		for _, brainDir := range brainDirs {
121			unlock, err := AcquireBrainWriteLock(brainDir)
122			if err != nil {
123				for i := len(unlocks) - 1; i >= 0; i-- {
124					unlocks[i]()
125				}
126				return nil, err
127			}
128			unlocks = append(unlocks, unlock)
129		}
130		release := func() {
131			for i := len(unlocks) - 1; i >= 0; i-- {
132				unlocks[i]()
133			}
134		}
135		if err := validateNormalizedRetrievalPolicies(byBrain, derivedClean, brainDirs, requireDerivedClean); err != nil {
136			release()
137			return nil, err
138		}
139		return release, nil
140	}
