1	package patterns
2	
3	import (
4		"fmt"
5		"os"
6	
7		"github.com/entireio/entire-brain/internal/cli/internal/base"
8		"github.com/entireio/entire-brain/internal/cli/internal/brainstore"
9		"github.com/entireio/entire-brain/internal/cli/workspace"
10	)
11	
12	// DerivedReadGate prevents the tombstone-first cleanup window from exposing
13	// corpus-derived content. A valid tombstone does not permanently disable
14	// patterns: once the authoritative full verification is clean, reads resume
15	// normally. verifyClean is the caller's full derived-projection verifier; it
16	// runs only while tombstones exist.
17	func DerivedReadGate(brainDir string, verifyClean func(string) (bool, error)) (bool, error) {
18		// The corpus is optional, but when present its main database and WAL must be
19		// ordinary Brain-owned files even when there are no tombstones. Without this
20		// unconditional check, best-effort pattern loaders could hide an unsafe alias
21		// as an empty result on status/get/skill surfaces.
22		if err := ValidateCorpusReadSafety(brainDir); err != nil {
23			return false, err
24		}
25		stones, _, err := brainstore.LoadSessionTombstonesChecked(brainDir)
26		if err != nil {
27			return false, err
28		}
29		if len(stones.Excluded) == 0 {
30			return true, nil
31		}
32		return verifyClean(brainDir)
33	}
34	
35	// VerifyDerivedClean is the full derived-projection verifier. A nil verifier
36	// fails closed: when tombstones exist and no verifier was supplied, derived
37	// reads are refused rather than assumed clean.
38	type VerifyDerivedClean func(brainDir string) (bool, error)
39	
40	func gateVerifier(verify VerifyDerivedClean) func(string) (bool, error) {
41		if verify != nil {
42			return func(brainDir string) (bool, error) { return verify(brainDir) }
43		}
44		return func(string) (bool, error) {
45			return false, fmt.Errorf("%s: derived-projection verifier unavailable; excluded-session cleanup cannot be proven clean", brainstore.PrivacyDirtyCode)
46		}
47	}
48	
49	// RequireDerivedRead fails unless the derived-read gate allows reads.
50	func RequireDerivedRead(brainDir string, verify VerifyDerivedClean) error {
51		allowed, err := DerivedReadGate(brainDir, gateVerifier(verify))
52		if err != nil {
53			return err
54		}
55		if !allowed {
56			return fmt.Errorf("%s: derived pattern state is unavailable until excluded-session cleanup verifies clean; run `"+base.BrainInvocation(os.LookupEnv, "privacy purge")+" <session-id>`", brainstore.PrivacyDirtyCode)
57		}
58		return nil
59	}
60	
61	// CaptureWorkspaceRetrievalPrivacyPolicies captures each member Brain's checked
62	// tombstone identity, deduplicated by repo key.
63	func CaptureWorkspaceRetrievalPrivacyPolicies(env base.EntireEnv, manifest workspace.Manifest) ([]brainstore.RetrievalPrivacyPolicy, map[string]string, error) {
64		policies := make([]brainstore.RetrievalPrivacyPolicy, 0, len(manifest.Repos))
65		byRepo := make(map[string]string, len(manifest.Repos))
66		for _, repo := range manifest.Repos {
67			if _, exists := byRepo[repo.RepoKey]; exists {
68				continue
69			}
70			brainDir, err := base.BrainDirForKey(env, repo.RepoKey)
71			if err != nil {
72				return nil, nil, err
73			}
74			policy, err := brainstore.CaptureRetrievalPrivacyPolicy(brainDir)
75			if err != nil {
76				return nil, nil, err
77			}
78			policies = append(policies, policy)
79			byRepo[repo.RepoKey] = policy.Identity
80		}
81		return policies, byRepo, nil
82	}
83	
84	// CaptureWorkspaceDerivedReadPolicies additionally proves every member's
85	// transcript-derived projections are clean before a workspace aggregate is
86	// read. Policy capture alone only proves the tombstone file did not change; it
87	// cannot make a corpus built before an already-present tombstone safe.
88	func CaptureWorkspaceDerivedReadPolicies(env base.EntireEnv, manifest workspace.Manifest, verify VerifyDerivedClean) ([]brainstore.RetrievalPrivacyPolicy, error) {
89		policies, _, err := CaptureWorkspaceRetrievalPrivacyPolicies(env, manifest)
90		if err != nil {
91			return nil, err
92		}
93		for i := range policies {
94			policy := &policies[i]
95			policy.RequireDerivedClean = true
96			allowed, gateErr := DerivedReadGate(policy.BrainDir, gateVerifier(verify))
97			if gateErr != nil {
98				return nil, gateErr
99			}
100			if !allowed {
101				return nil, fmt.Errorf("%s: workspace member has unverified transcript-derived projections: %s", brainstore.PrivacyDirtyCode, policy.BrainDir)
102			}
103		}
104		// Workspace pattern/theme/family rows live in their own aggregate corpus.
105		// Give that Brain the same final-emission proof as every member so a corpus
106		// alias or replacement after assembly cannot be collapsed into empty output.
107		wsDir, err := workspace.DefaultStore(env).Dir(manifest.Name)
108		if err != nil {
109			return nil, err
110		}
111		wsPolicy, err := brainstore.CaptureRetrievalPrivacyPolicy(wsDir)
112		if err != nil {
113			return nil, err
114		}
115		wsPolicy.RequireDerivedClean = true
116		if err := RequireDerivedRead(wsDir, verify); err != nil {
117			return nil, err
118		}
119		policies = append(policies, wsPolicy)
120		return policies, nil
121	}
