1	package cli
2	
3	import (
4		"bytes"
5		"fmt"
6		"io"
7	
8		"github.com/spf13/cobra"
9	)
10	
11	// runPrivacyLinearizedPatternMutation is the commit/egress boundary for the
12	// explicit pattern operations which may send transcript-derived material to a
13	// provider or persist a derived result. Unlike an ordinary retrieval, provider
14	// egress cannot be revoked after it starts. The sorted Brain locks therefore
15	// remain held from the final derived-state check through provider execution,
16	// persistence, and emission of the completely buffered command response.
17	//
18	// This deliberately trades bounded exclusion/purge latency (the provider
19	// timeout) for a real privacy linearization point. Holding only an epoch token
20	// would be insufficient: a tombstone could commit after the request bytes had
21	// reached the provider but before a later epoch check noticed it.
22	func runPrivacyLinearizedPatternMutation(cmd *cobra.Command, policies []retrievalPrivacyPolicy, mutate func() error) error {
23		for i := range policies {
24			policies[i].RequireDerivedClean = true
25		}
26		originalOut := cmd.OutOrStdout()
27		originalErr := cmd.ErrOrStderr()
28		var stdout, stderr bytes.Buffer
29		cmd.SetOut(&stdout)
30		cmd.SetErr(&stderr)
31		defer func() {
32			cmd.SetOut(originalOut)
33			cmd.SetErr(originalErr)
34		}()
35	
36		return withLockedRetrievalPrivacyPolicies(policies, func() error {
37			// Policy identity alone is not enough: a cleanup transaction may still
38			// mark derived projections dirty under that same tombstone generation.
39			for _, policy := range policies {
40				if policy.BrainDir == "" {
41					continue
42				}
43				if err := requirePrivacyDerivedRead(policy.BrainDir); err != nil {
44					return err
45				}
46			}
47			if err := mutate(); err != nil {
48				return err
49			}
50			cmd.SetOut(originalOut)
51			cmd.SetErr(originalErr)
52			if err := writeAllCommandBytes(originalOut, stdout.Bytes()); err != nil {
53				return err
54			}
55			return writeAllCommandBytes(originalErr, stderr.Bytes())
56		})
57	}
58	
59	func writeAllCommandBytes(out io.Writer, data []byte) error {
60		if len(data) == 0 {
61			return nil
62		}
63		n, err := out.Write(data)
64		if err == nil && n != len(data) {
65			return io.ErrShortWrite
66		}
67		if err != nil {
68			return fmt.Errorf("write command output: %w", err)
69		}
70		return nil
71	}
