90	type sessionListEntry struct {
91		SessionID      string `json:"session_id"`
92		Branch         string `json:"branch,omitempty"`
93		Agent          string `json:"agent,omitempty"`
94		CreatedAt      string `json:"created_at,omitempty"`
95		TranscriptPath string `json:"transcript_path"`
96		Excluded       bool   `json:"excluded,omitempty"`
97		ExcludedAt     string `json:"excluded_at,omitempty"`
98		Reason         string `json:"reason,omitempty"`
99		// Unmatched marks a tombstone that no captured session in this brain
100		// answers to -- either armed pre-emptively before capture, or left behind
101		// by a session a later refresh dropped. It is a real, active exclusion
102		// either way, so it is still listed; it is just not evidence that anything
103		// was ever removed, and rendering it identically to a matched exclusion is
104		// what let a typo look like a completed cleanup forever.
105		Unmatched bool `json:"unmatched,omitempty"`
106	}
