108	func newSessionsListCommand(opts Options) *cobra.Command {
109		var jsonOut bool
110		cmd := &cobra.Command{
111			Use:   "list",
112			Short: "List captured sessions and their exclusion state",
113			Args:  cobra.NoArgs,
114			RunE: func(cmd *cobra.Command, args []string) error {
115				storage, err := resolveSessionsBrain(cmd.Context(), opts)
116				if err != nil {
117					return err
118				}
119				brainDir := storage.BrainDir
120				manifest, err := bmanifest.Load(brainDir)
121				if err != nil {
122					return err
123				}
124				stones, _, err := brainstore.LoadSessionTombstonesChecked(brainDir)
125				if err != nil {
126					return err
127				}
128				var entries []sessionListEntry
129				if manifest.Sources != nil && manifest.Sources.Sessions != nil {
130					for _, session := range manifest.Sources.Sessions.Sessions {
131						entry := sessionListEntry{
132							SessionID: session.SessionID, Branch: session.Branch, Agent: session.Agent,
133							TranscriptPath: session.TranscriptPath,
134						}
135						if !session.CreatedAt.IsZero() {
136							entry.CreatedAt = session.CreatedAt.UTC().Format(time.RFC3339)
137						}
138						if stone, excluded := stones.Excluded[session.SessionID]; excluded {
139							entry.Excluded = true
140							entry.ExcludedAt = stone.At.UTC().Format(time.RFC3339)
141							entry.Reason = stone.Reason
142						}
143						entries = append(entries, entry)
144					}
145				}
146				sort.Slice(entries, func(i, j int) bool { return entries[i].CreatedAt > entries[j].CreatedAt })
147				// Tombstones for sessions no longer in the manifest still matter
148				// (they keep a re-export from re-indexing); list them too.
149				known := map[string]bool{}
150				for _, entry := range entries {
151					known[entry.SessionID] = true
152				}
153				for id, stone := range stones.Excluded {
154					if !known[id] {
155						entries = append(entries, sessionListEntry{SessionID: id, Excluded: true, Unmatched: true, ExcludedAt: stone.At.UTC().Format(time.RFC3339), Reason: stone.Reason})
156					}
157				}
158				if jsonOut {
159					if entries == nil {
160						entries = []sessionListEntry{}
161					}
162					return cmdutil.WriteJSON(cmd, map[string]any{"sessions": entries})
163				}
164				return cmdutil.WriteText(cmd, func(out io.Writer) {
165					// An empty session list is the normal state of a brain that has
166					// never captured a session, and printing nothing for it made the
167					// one command a privacy-conscious user reaches for indistinguishable
168					// from a command that failed to look. Say which it is.
169					if len(entries) == 0 {
170						fmt.Fprintln(out, "no captured sessions in this brain")
171						return
172					}
173					unmatched := 0
174					for _, entry := range entries {
175						state := "included"
176						switch {
177						case entry.Excluded && entry.Unmatched:
178							// Distinct from EXCLUDED on purpose. The row is the
179							// only place a user can notice that the id they typed
180							// matched nothing -- every other column is <unset>,
181							// which reads as missing metadata rather than as a
182							// tombstone waiting for a session that may never exist.
183							state = "UNMATCHED"
184							unmatched++
185						case entry.Excluded:
186							state = "EXCLUDED"
187						}
188						fmt.Fprintf(out, "%-10s %s  %s  %s  %s\n", state, cmdutil.ValueOrUnset(entry.SessionID), cmdutil.ValueOrUnset(entry.CreatedAt), cmdutil.ValueOrUnset(entry.Agent), entry.TranscriptPath)
189					}
190					if unmatched > 0 {
191						fmt.Fprintf(out, "UNMATCHED: %d tombstone(s) match no captured session in this brain; each stays recorded and applies if such a session is captured later\n", unmatched)
192					}
193				})
194			},
195		}
196		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit machine-readable JSON")
197		return cmd
198	}
