235	func runSessionsExclude(ctx context.Context, cmd *cobra.Command, opts Options, sessionID, reason string, jsonOut bool) error {
236		sessionID = strings.TrimSpace(sessionID)
237		if sessionID == "" {
238			return fmt.Errorf("session id is required")
239		}
240		storage, err := resolveSessionsBrain(ctx, opts)
241		if err != nil {
242			return err
243		}
244		brainDir := storage.BrainDir
245		var plan sessionPurgePlan
246		matched := false
247		if err := brainstore.WithBrainPrivacySideEffectLock(brainDir, func() error {
248			return brainstore.WithBrainWriteLock(brainDir, func() error {
249				// Exclusion is purge minus the transcript: the tombstone guards
250				// reads immediately, then every derived projection the session fed --
251				// index records, facts, episodes, pattern outputs, caches, FTS and
252				// vector stores -- is removed or rebuilt from the surviving truth.
253				// Errors propagate; a partial cleanup is a failure, not a success.
254				var planErr error
255				plan, planErr = buildSessionPurgePlan(brainDir, sessionID)
256				if planErr != nil {
257					return planErr
258				}
259				manifest, manifestErr := bmanifest.Load(brainDir)
260				if manifestErr != nil {
261					return manifestErr
262				}
263				matched = sessionExclusionMatchedSomething(manifest, plan, sessionID)
264				return executeSessionCleanup(brainDir, sessionID, plan, opts.Now().UTC(), strings.TrimSpace(reason), true)
265			})
266		}); err != nil {
267			return err
268		}
269		if jsonOut {
270			return cmdutil.WriteJSON(cmd, map[string]any{
271				"excluded": sessionID,
272				// matched says whether anything in this brain answered to the id.
273				// A false here is not a failure: the tombstone is recorded and
274				// will apply to a session captured later. It is the difference
275				// between "cleaned up" and "armed", which the caller cannot infer
276				// from the exit code.
277				"matched":               matched,
278				"records":               plan.Records,
279				"facts_deleted":         plan.FactsDeleted,
280				"fact_anchors_stripped": plan.FactAnchorsStripped,
281				"episodes":              plan.Episodes,
282				"transcripts":           len(plan.Transcripts),
283			})
284		}
285		return cmdutil.WriteText(cmd, func(out io.Writer) {
286			// Report what happened, not what the command is for. Excluding an id no
287			// session in this brain answers to is a legitimate PRE-EMPTIVE privacy
288			// operation -- arming the tombstone before capture is strictly safer
289			// than refusing it and losing the race -- so the operation stays
290			// permitted and keeps exiting 0. What was wrong was the sentence: it
291			// claimed to have "removed or rebuilt its derived projections" for a
292			// session that had produced none, which is the same class of lie as
293			// under-reporting a real cleanup. `purge` already reports its real
294			// inventory on the same plan; exclude now does too.
295			if !matched {
296				fmt.Fprintf(out, "excluded %s: tombstone recorded, nothing to remove or rebuild\n", sessionID)
297				fmt.Fprintln(out, "  no captured session in this brain matches this id")
298				fmt.Fprintln(out, "  the tombstone stays recorded and applies if such a session is captured later")
299				return
300			}
301			fmt.Fprintf(out, "excluded %s and removed or rebuilt its derived projections:\n", sessionID)
302			fmt.Fprintf(out, "  %d derived index records\n", plan.Records)
303			if plan.FactsDeleted > 0 || plan.FactAnchorsStripped > 0 {
304				fmt.Fprintf(out, "  %d single-source memories deleted, %d anchors stripped from corroborated memories\n", plan.FactsDeleted, plan.FactAnchorsStripped)
305			}
306			if plan.Episodes > 0 {
307				fmt.Fprintf(out, "  %d pattern episodes\n", plan.Episodes)
308			}
309			for _, artifact := range plan.DerivedStores {
310				fmt.Fprintf(out, "  derived store %s (%d bytes, rebuilds from surviving truth)\n", artifact.Path, artifact.Bytes)
311			}
312		})
313	}
314	
315	// sessionExclusionMatchedSomething reports whether anything in this brain
316	// actually answers to the excluded or purged id.
317	//
318	// The evidence is deliberately drawn from the manifest and from the plan's
319	// manifest-derived counts only -- never from the privacy transaction record or
320	// the wholesale derived-store inventory. Both of those are non-empty for an id
321	// this brain has never seen: the transaction is written by the exclusion
322	// itself, and the rebuildable stores (scan caches, FTS, vectors) are dropped
323	// unconditionally. Counting either would make a repeated exclusion of the same
324	// phantom report itself as a real cleanup on the second run.
325	func sessionExclusionMatchedSomething(manifest *exportManifest, plan sessionPurgePlan, sessionID string) bool {
326		if len(plan.Transcripts) > 0 || plan.Records > 0 || plan.FactsDeleted > 0 || plan.FactAnchorsStripped > 0 || plan.Episodes > 0 {
327			return true
328		}
329		return manifestHasCapturedSession(manifest, sessionID)
330	}
331	
332	// manifestHasCapturedSession reports whether the brain manifest lists this
333	// session id as captured. A session with no transcript path and no derived
334	// records still counts: it was captured, so excluding it is not pre-emptive.
335	func manifestHasCapturedSession(manifest *exportManifest, sessionID string) bool {
336		if manifest == nil || manifest.Sources == nil || manifest.Sources.Sessions == nil {
337			return false
338		}
339		for _, session := range manifest.Sources.Sessions.Sessions {
340			if strings.TrimSpace(session.SessionID) == sessionID {
341				return true
342			}
343		}
344		return false
345	}
