378	// rebuildSessionHistoryForIncludeLocked is an injected commit seam for the
379	// re-include transaction. Production uses the same generation-addressed,
380	// manifest-last history publisher as refresh; tests fail or pause this exact
381	// boundary to prove rollback and lock ordering.
382	var rebuildSessionHistoryForIncludeLocked = func(brainDir string, now time.Time) error {
383		_, err := writeBrainHistoryIndexAndSourceLocked(brainDir, now, nil)
384		return err
