387	// beforeIncludePrivacyTransactionDirSync is injectable so the
388	// unlink-succeeded/sync-failed transaction outcome is deterministic in tests.
389	var beforeIncludePrivacyTransactionDirSync = func(string) error { return nil }
390	
391	type includePrivacyRollback struct {
392		tombstonesBefore   []byte
393		tombstonesAfter    []byte
394		transactionRel     string
395		transactionBefore  []byte
396		transactionPresent bool
397	}
398	
399	// includeSessionLocked removes one exclusion and rebuilds the including history
400	// generation as one externally atomic operation. The caller holds the privacy
401	// side-effect lock before the Brain write lock, so no cooperative read, provider
402	// side effect, or privacy mutation can observe the temporary policy. If any
403	// pre-commit step fails, the exact validated tombstone and transaction bytes are
404	// restored before either lock is released, leaving the same command retryable.
405	func includeSessionLocked(brainDir, sessionID string, now time.Time) error {
406		stones, tombstoneState, err := brainstore.LoadSessionTombstonesChecked(brainDir)
407		if err != nil {
408			return err
409		}
410		if _, ok := stones.Excluded[sessionID]; !ok {
411			return fmt.Errorf("session %s is not excluded", sessionID)
412		}
413		tombstonesBefore, present, err := brainstore.ReadPrivacyArtifact(brainDir, brainstore.SessionTombstonesPath, "session tombstones", clibase.MaxManifestBytes)
414		if err != nil {
415			return err
416		}
417		if !present || privacyBytesIdentity(tombstonesBefore) != tombstoneState.Identity {
418			return fmt.Errorf("%s: session tombstones changed before include", brainstore.StateUnsafeCode)
419		}
420		_, transactionPresent, err := brainstore.LoadPrivacyTransactionChecked(brainDir, sessionID)
421		if err != nil {
422			return err
423		}
424		var transactionBefore []byte
425		transactionRel := brainstore.PrivacyTransactionRel(sessionID)
426		if transactionPresent {
427			transactionBefore, present, err = brainstore.ReadPrivacyArtifact(brainDir, transactionRel, "privacy transaction", clibase.MaxManifestBytes)
428			if err != nil {
429				return err
430			}
431			if !present {
432				return fmt.Errorf("%s: privacy transaction disappeared before include", brainstore.StateUnsafeCode)
433			}
434			if _, err := brainstore.DecodePrivacyTransaction(transactionBefore, sessionID); err != nil {
435				return err
436			}
437		}
438	
439		delete(stones.Excluded, sessionID)
440		tombstonesAfter, err := brainstore.MarshalSessionTombstones(stones)
441		if err != nil {
442			return err
443		}
444		rollback := includePrivacyRollback{
445			tombstonesBefore: tombstonesBefore, tombstonesAfter: tombstonesAfter,
446			transactionRel: transactionRel, transactionBefore: transactionBefore, transactionPresent: transactionPresent,
447		}
448		if err := brainstore.SaveSessionTombstones(brainDir, stones); err != nil {
449			// Atomic replacement can report a durability failure after rename made
450			// the included policy visible. The result is therefore ambiguous: always
451			// inspect and restore the exact prior state before releasing either lock.
452			return errors.Join(err, restoreIncludePrivacyState(brainDir, rollback))
453		}
454		currentTombstones, present, err := brainstore.ReadPrivacyArtifact(brainDir, brainstore.SessionTombstonesPath, "included session tombstones", clibase.MaxManifestBytes)
455		if err != nil || !present || !bytes.Equal(currentTombstones, tombstonesAfter) {
456			if err == nil {
457				err = fmt.Errorf("%s: session tombstones changed while including %s", brainstore.StateUnsafeCode, sessionID)
458			}
459			return errors.Join(err, restoreIncludePrivacyState(brainDir, rollback))
460		}
461		// Re-include is a clean slate: the old cleanup transaction no longer
462		// describes a live exclusion. Removing it before the rebuild also means a
463		// successful manifest switch cannot be followed by a fallible cleanup step.
464		if err := removePrivacyTransactionForInclude(brainDir, sessionID, transactionPresent); err != nil {
465			return errors.Join(err, restoreIncludePrivacyState(brainDir, rollback))
466		}
467		if err := rebuildSessionHistoryForIncludeLocked(brainDir, now); err != nil {
468			return errors.Join(err, restoreIncludePrivacyState(brainDir, rollback))
469		}
470		// Cleanup stripped this session's id out of the derived entity join. The
471		// join is recomputed from the durable git-meta store, which the exclusion
472		// never touched, so the linkage comes back the moment the join is rebuilt —
473		// but the cache is pinned to the git-meta tip, which an include does not
474		// move, so without this the re-included session would stay missing from
475		// `entities history` indefinitely. Unpinning it is best-effort on purpose:
476		// a failed rebuild falls back to serving this same (still privacy-clean)
477		// cache, so nothing is lost and include must not fail over an accelerator.
478		invalidateEntityIndexJoin(brainDir)
479		return nil
480	}
481	
482	// invalidateEntityIndexJoin unpins the derived entity index from the git-meta
483	// tip so the next read recomputes it. It deliberately clears the pin rather
484	// than deleting the file: the rebuild needs the Graph provider, and on a
485	// machine without it a deleted cache could never be recreated, while an
486	// unpinned one is still served.
487	func invalidateEntityIndexJoin(brainDir string) {
488		cache, present, err := loadPrivacyEntityIndex(brainDir)
489		if err != nil || !present || cache.MetaTip == "" {
490			return
491		}
492		cache.MetaTip = ""
493		data, err := json.Marshal(cache)
494		if err != nil {
495			return
496		}
497		_ = brainstore.WriteBrainRelativeFileAtomic(brainDir, entities.CachePath, append(data, '\n'), 0o600)
498	}
499	
500	func privacyBytesIdentity(data []byte) string {
501		sum := sha256.Sum256(data)
502		return "sha256:" + hex.EncodeToString(sum[:])
503	}
504	
505	// restoreIncludePrivacyState refuses to overwrite any unexpected concurrent or
506	// forward-version leaf. Cooperative writers cannot enter while include holds
507	// the Brain lock, but exact checks keep rollback non-destructive even under an
508	// out-of-process or adversarial replacement.
509	func restoreIncludePrivacyState(brainDir string, rollback includePrivacyRollback) error {
510		var restoreErr error
511		currentTombstones, present, err := brainstore.ReadPrivacyArtifact(brainDir, brainstore.SessionTombstonesPath, "session tombstones during include rollback", clibase.MaxManifestBytes)
512		switch {
513		case err != nil:
514			restoreErr = errors.Join(restoreErr, err)
515		case present && bytes.Equal(currentTombstones, rollback.tombstonesBefore):
516			// A failed atomic replacement may already have left the original bytes.
517		case !present || len(rollback.tombstonesAfter) == 0 || !bytes.Equal(currentTombstones, rollback.tombstonesAfter):
518			restoreErr = errors.Join(restoreErr, fmt.Errorf("%s: session tombstones changed during include rollback", brainstore.StateUnsafeCode))
519		default:
520			if err := restoreIncludePrivacyFile(brainDir, brainstore.SessionTombstonesPath, "session tombstones", rollback.tombstonesBefore); err != nil {
521				restoreErr = errors.Join(restoreErr, fmt.Errorf("restore session tombstones after failed include: %w", err))
522			}
523		}
524	
525		currentTransaction, transactionPresent, err := brainstore.ReadPrivacyArtifact(brainDir, rollback.transactionRel, "privacy transaction during include rollback", clibase.MaxManifestBytes)
526		switch {
527		case err != nil:
528			restoreErr = errors.Join(restoreErr, err)
529		case !rollback.transactionPresent && !transactionPresent:
530		case !rollback.transactionPresent:
531			restoreErr = errors.Join(restoreErr, fmt.Errorf("%s: privacy transaction appeared during include rollback", brainstore.StateUnsafeCode))
532		case transactionPresent && bytes.Equal(currentTransaction, rollback.transactionBefore):
533		case transactionPresent:
534			restoreErr = errors.Join(restoreErr, fmt.Errorf("%s: privacy transaction changed during include rollback", brainstore.StateUnsafeCode))
535		default:
536			if err := restoreIncludePrivacyFile(brainDir, rollback.transactionRel, "privacy transaction", rollback.transactionBefore); err != nil {
537				restoreErr = errors.Join(restoreErr, fmt.Errorf("restore privacy transaction after failed include: %w", err))
538			}
539		}
540		return errors.Join(restoreErr, verifyIncludePrivacyRollback(brainDir, rollback))
541	}
542	
543	func verifyIncludePrivacyRollback(brainDir string, rollback includePrivacyRollback) error {
544		var verifyErr error
545		if err := requireExactIncludePrivacyFile(brainDir, brainstore.SessionTombstonesPath, "session tombstones", rollback.tombstonesBefore); err != nil {
546			verifyErr = errors.Join(verifyErr, err)
547		}
548		current, present, err := brainstore.ReadPrivacyArtifact(brainDir, rollback.transactionRel, "privacy transaction after include rollback", clibase.MaxManifestBytes)
549		switch {
550		case err != nil:
551			verifyErr = errors.Join(verifyErr, err)
552		case rollback.transactionPresent && (!present || !bytes.Equal(current, rollback.transactionBefore)):
553			verifyErr = errors.Join(verifyErr, fmt.Errorf("%s: exact privacy transaction rollback bytes are not live", brainstore.StateUnsafeCode))
554		case !rollback.transactionPresent && present:
555			verifyErr = errors.Join(verifyErr, fmt.Errorf("%s: unexpected privacy transaction is live after rollback", brainstore.StateUnsafeCode))
556		}
557		return verifyErr
558	}
