560	// restoreIncludePrivacyFile resolves the only ambiguous atomic-write failure:
561	// rename succeeded but syncing the parent directory did not. It proves the
562	// exact rollback bytes are live, performs the missing durability barrier, and
563	// proves them again. Every other write failure remains an error; callers never
564	// infer successful rollback from an unclassified failure.
565	func restoreIncludePrivacyFile(brainDir, rel, label string, before []byte) error {
566		err := brainstore.WriteBrainRelativeFileAtomic(brainDir, rel, before, 0o600)
567		if err == nil {
568			return nil
569		}
570		var durabilityErr *brainstore.AtomicReplaceDurabilityError
571		if !errors.As(err, &durabilityErr) {
572			return err
573		}
574		if exactErr := requireExactIncludePrivacyFile(brainDir, rel, label, before); exactErr != nil {
575			return errors.Join(err, exactErr)
576		}
577		if rootErr := clibase.RejectSymlinkedBrainRoot(brainDir); rootErr != nil {
578			return errors.Join(err, rootErr)
579		}
580		clean, cleanErr := clibase.CleanBrainRelativePath(rel)
581		if cleanErr != nil {
582			return errors.Join(err, cleanErr)
583		}
584		if syncErr := brainstore.SyncParentDir(filepath.Join(brainDir, clean)); syncErr != nil {
585			return errors.Join(err, fmt.Errorf("sync restored %s directory: %w", label, syncErr))
586		}
587		if exactErr := requireExactIncludePrivacyFile(brainDir, rel, label, before); exactErr != nil {
588			return errors.Join(err, exactErr)
589		}
590		return nil
591	}
592	
593	func requireExactIncludePrivacyFile(brainDir, rel, label string, want []byte) error {
594		current, present, err := brainstore.ReadPrivacyArtifact(brainDir, rel, label+" after include rollback", clibase.MaxManifestBytes)
595		if err != nil {
596			return err
597		}
598		if !present || !bytes.Equal(current, want) {
599			return fmt.Errorf("%s: exact %s rollback bytes are not live", brainstore.StateUnsafeCode, label)
600		}
601		return nil
602	}
