604	// sessionPurgePlan is the dry-run contract: exactly the artifacts (and their
605	// current bytes) a purge would remove or rebuild.
606	type sessionPurgePlan struct {
607		SessionID string `json:"session_id"`
608		// SessionRefs are content-free canonical conversation identities captured
609		// before the tombstone lands. They remain durable in the privacy transaction
610		// so a retry can remove abstracts/egress even if refresh later drops or
611		// renames the manifest session entry.
612		SessionRefs []string `json:"session_refs,omitempty"`
613		// Transcripts are the exported local copies that will be deleted.
614		Transcripts []purgeArtifact `json:"transcripts"`
615		// Records is the number of index records (all kinds) derived from those
616		// transcripts that the rebuild will drop.
617		Records int `json:"records"`
618		// FactsDeleted counts durable facts whose ONLY provenance is the purged
619		// session (physically removed); FactAnchorsStripped counts purged-session
620		// anchors removed from facts that remain corroborated by other sessions.
621		FactsDeleted        int `json:"facts_deleted"`
622		FactAnchorsStripped int `json:"fact_anchors_stripped"`
623		// Episodes counts pattern-layer episode records derived from the session.
624		Episodes int `json:"episodes"`
625		// DerivedStores are rebuildable stores deleted wholesale (they regenerate
626		// from the surviving truth on the next query/refresh/patterns build).
627		// skill-memory.ndjson is deliberately NOT here: it holds user curation
628		// decisions (ids/status/counters, no transcript content), not derivation.
629		DerivedStores []purgeArtifact `json:"derived_stores"`
630		// WorkMetadata is content-free lifecycle/job state tied to this raw
631		// session. Privacy cleanup removes it immediately rather than retaining
632		// operational evidence about a session the user excluded or purged.
633		WorkMetadata []purgeArtifact `json:"work_metadata,omitempty"`
634		// Caveats name locations a purge does NOT clean, so incomplete deletion is
635		// explicit rather than silent (e.g. the `facts sync` git-meta store, whose
636		// keep-both merge model has no deletion semantics yet).
637		Caveats []string `json:"caveats,omitempty"`
638		DryRun  bool     `json:"dry_run"`
639		// Matched says whether anything in this brain answered to the id, exactly
640		// as exclude's JSON reports it. A false is not a failure: the tombstone is
641		// still recorded and applies to a session captured later. The caller cannot
642		// infer this from the counts alone -- a captured session can legitimately
643		// have zero remaining artifacts.
644		Matched bool `json:"matched"`
645	}
