662	func runSessionsPurge(ctx context.Context, cmd *cobra.Command, opts Options, sessionID string, dryRun, jsonOut bool) error {
663		sessionID = strings.TrimSpace(sessionID)
664		if sessionID == "" {
665			return fmt.Errorf("session id is required")
666		}
667		storage, err := resolveSessionsBrain(ctx, opts)
668		if err != nil {
669			return err
670		}
671		brainDir := storage.BrainDir
672		var plan sessionPurgePlan
673		apply := func() error {
674			return brainstore.WithBrainWriteLock(brainDir, func() error {
675				var planErr error
676				plan, planErr = buildSessionPurgePlan(brainDir, sessionID)
677				if planErr != nil {
678					return planErr
679				}
680				manifest, manifestErr := bmanifest.Load(brainDir)
681				if manifestErr != nil {
682					return manifestErr
683				}
684				plan.Matched = sessionExclusionMatchedSomething(manifest, plan, sessionID)
685				plan.Caveats = append(plan.Caveats, purgeGitmetaSyncCaveats(opts.Env, storage.Key, plan)...)
686				plan.DryRun = dryRun
687				if dryRun {
688					return nil
689				}
690				return executeSessionPurge(brainDir, sessionID, plan, opts.Now().UTC())
691			})
692		}
693		if !dryRun {
694			operation := apply
695			apply = func() error { return brainstore.WithBrainPrivacySideEffectLock(brainDir, operation) }
696		}
697		if err := apply(); err != nil {
698			return err
699		}
700		if jsonOut {
701			return cmdutil.WriteJSON(cmd, plan)
702		}
703		return cmdutil.WriteText(cmd, func(out io.Writer) {
704			// Same honesty rule as exclude: an id no captured session answers to
705			// must not report as a cleanup. The tombstone still lands (pre-emptive
706			// arming is strictly safer than refusing and losing the race), so the
707			// operation stays permitted and keeps exiting 0, like exclude.
708			if !plan.Matched {
709				if plan.DryRun {
710					fmt.Fprintf(out, "purge (dry-run) %s: nothing to remove or rebuild\n", plan.SessionID)
711					fmt.Fprintln(out, "  no captured session in this brain matches this id")
712					return
713				}
714				fmt.Fprintf(out, "purged %s: tombstone recorded, nothing to remove or rebuild\n", plan.SessionID)
715				fmt.Fprintln(out, "  no captured session in this brain matches this id")
716				fmt.Fprintln(out, "  the tombstone stays recorded and applies if such a session is captured later")
717				return
718			}
719			mode := "purged"
720			if plan.DryRun {
721				mode = "purge (dry-run) would remove"
722			}
723			fmt.Fprintf(out, "%s session %s:\n", mode, plan.SessionID)
724			for _, artifact := range plan.Transcripts {
725				fmt.Fprintf(out, "  transcript %s (%d bytes)\n", artifact.Path, artifact.Bytes)
726			}
727			fmt.Fprintf(out, "  %d derived index records\n", plan.Records)
728			if plan.FactsDeleted > 0 || plan.FactAnchorsStripped > 0 {
729				fmt.Fprintf(out, "  %d single-source memories deleted, %d anchors stripped from corroborated memories\n", plan.FactsDeleted, plan.FactAnchorsStripped)
730			}
731			if plan.Episodes > 0 {
732				fmt.Fprintf(out, "  %d pattern episodes\n", plan.Episodes)
733			}
734			for _, artifact := range plan.DerivedStores {
735				fmt.Fprintf(out, "  derived store %s (%d bytes, rebuilds from surviving truth)\n", artifact.Path, artifact.Bytes)
736			}
737			for _, artifact := range plan.WorkMetadata {
738				fmt.Fprintf(out, "  memory work metadata %s (%d bytes)\n", artifact.Path, artifact.Bytes)
739			}
740			for _, caveat := range plan.Caveats {
741				fmt.Fprintf(out, "  NOT purged: %s\n", caveat)
742			}
743		})
744	}
