841	func factAnchorMatchesSession(anchor factAnchor, sessionID string, transcriptRels map[string]bool) bool {
842		if strings.TrimSpace(anchor.SessionID) == strings.TrimSpace(sessionID) {
843			return true
844		}
845		rel := brainstore.NormalizePrivacyTranscriptPath(anchor.Transcript)
846		return rel != "" && transcriptRels[rel]
847	}
