849	func buildSessionPurgePlan(brainDir, sessionID string) (sessionPurgePlan, error) {
850		plan := sessionPurgePlan{SessionID: sessionID}
851		manifest, err := bmanifest.Load(brainDir)
852		if err != nil {
853			return plan, err
854		}
855		refSet := sessionRefsForSessionID(brainDir, manifest, sessionID)
856		priorTx, priorPresent, err := brainstore.LoadPrivacyTransactionChecked(brainDir, sessionID)
857		if err != nil {
858			return plan, err
859		}
860		if priorPresent {
861			for _, ref := range priorTx.SessionRefs {
862				refSet[ref] = true
863			}
864		}
865		transcriptRels := map[string]bool{}
866		priorPaths, err := brainstore.PrivacyTransactionTranscriptPaths(priorTx)
867		if err != nil {
868			return plan, err
869		}
870		for _, rel := range priorPaths {
871			transcriptRels[rel] = true
872		}
873		if manifest.Sources != nil && manifest.Sources.Sessions != nil {
874			for _, session := range manifest.Sources.Sessions.Sessions {
875				if strings.TrimSpace(session.SessionID) == sessionID {
876					if rel := brainstore.NormalizePrivacyTranscriptPath(session.TranscriptPath); rel != "" {
877						transcriptRels[rel] = true
878					}
879				}
880			}
881		}
882		// Keep missing paths in the durable scope too: a later re-export must
883		// remain detectable even after the manifest has forgotten this session.
884		for rel := range transcriptRels {
885			artifact := purgeArtifact{Path: rel}
886			info, present, statErr := brainstore.PrivacyArtifactInfo(brainDir, rel, "session transcript")
887			if statErr != nil {
888				return plan, statErr
889			}
890			if present {
891				artifact.Bytes = info.Size()
892			}
893			plan.Transcripts = append(plan.Transcripts, artifact)
894		}
895		sort.Slice(plan.Transcripts, func(i, j int) bool { return plan.Transcripts[i].Path < plan.Transcripts[j].Path })
896		if manifest.Sources != nil && manifest.Sources.History != nil {
897			// A declared-but-unreadable index is a real storage problem: failing
898			// here beats an under-reported plan that execution would then trust
899			// (dry-run and execution inventories must match).
900			index, ierr := historystore.LoadIndex(brainDir, manifest.Sources.History)
901			if ierr != nil {
902				return plan, fmt.Errorf("load history index: %w", ierr)
903			}
904			for _, record := range index.Records {
905				if transcriptRels[record.Path] {
906					plan.Records++
907				}
908			}
909		}
910		// Facts derived from the purged session (single-source facts are deleted;
911		// multi-source facts only lose the purged anchor). A corrupt fact store is
912		// an error, not an empty count.
913		byBranch, ferr := loadAllFactBranchesForPrivacy(brainDir)
914		if ferr != nil {
915			return plan, fmt.Errorf("load facts: %w", ferr)
916		}
917		for _, facts := range byBranch {
918			for _, fact := range facts {
919				matched, remaining := 0, 0
920				for _, anchor := range fact.Provenance {
921					if factAnchorMatchesSession(anchor, sessionID, transcriptRels) {
922						matched++
923					} else {
924						remaining++
925					}
926				}
927				switch {
928				case matched > 0 && remaining == 0:
929					plan.FactsDeleted++
930				case matched > 0:
931					plan.FactAnchorsStripped += matched
932				}
933			}
934		}
935		// Pattern-layer episodes derived from the session.
936		plan.Episodes, err = countSessionEpisodes(brainDir, sessionID, transcriptRels)
937		if err != nil {
938			return plan, err
939		}
940		// Rebuildable derived stores removed wholesale: their row-level content is
941		// keyed by record ids/text derived from the purged transcripts, and every
942		// one regenerates from the surviving truth (index rebuild, lazy FTS build,
943		// next vector sync, next patterns build). runs.ndjson is a build log and
944		// logs are inside the plan's deletion inventory.
945		derivedArtifacts, inventoryErr := privacyDerivedStoreArtifacts(brainDir)
946		if inventoryErr != nil {
947			return plan, inventoryErr
948		}
949		for _, rel := range derivedArtifacts {
950			info, present, statErr := brainstore.PrivacyArtifactInfo(brainDir, rel, "derived privacy store")
951			if statErr != nil {
952				return plan, statErr
953			}
954			if present {
955				plan.DerivedStores = append(plan.DerivedStores, purgeArtifact{Path: rel, Bytes: info.Size()})
956			}
957		}
958		// Durable memory hints/jobs are intentionally content-free, but they still
959		// retain the identity and lifecycle of this session. Include their exact
960		// files in dry-run and execution inventories so privacy cleanup is complete
961		// and auditable.
962		hints, hintIssues := loadMemoryHintsChecked(brainDir)
963		jobInventory := loadMemoryJobInventory(brainDir)
964		if err := memoryStateError(append(hintIssues, jobInventory.Issues...)); err != nil {
965			return plan, err
966		}
967		addWork := func(rel string) error {
968			artifact := purgeArtifact{Path: rel}
969			info, present, statErr := brainstore.PrivacyArtifactInfo(brainDir, rel, "memory work metadata")
970			if statErr != nil {
971				return statErr
972			}
973			if present {
974				artifact.Bytes = info.Size()
975			}
976			plan.WorkMetadata = append(plan.WorkMetadata, artifact)
977			return nil
978		}
979		for _, hint := range hints {
980			if hint.SessionID == sessionID {
981				if err := addWork(memoryHintRel(hint.RepoKey, hint.SessionID, hint.Branch)); err != nil {
982					return plan, err
983				}
984			}
985		}
986		for _, job := range jobInventory.Jobs {
987			if job.SessionID != sessionID {
988				continue
989			}
990			if ref := strings.TrimSpace(job.SessionRef); ref != "" {
991				if !strings.HasPrefix(ref, brainstore.ConversationSessionIDPrefix) {
992					return plan, fmt.Errorf("%s: abstract job has invalid session ref", brainstore.StateCorruptCode)
993				}
994				refSet[ref] = true
995			}
996			for _, rel := range memoryJobSourcePaths(job) {
997				if err := addWork(rel); err != nil {
998					return plan, err
999				}
1000			}
1001			cancellationRel := memoryCancellationRel(job.JobID)
1002			_, present, statErr := brainstore.PrivacyArtifactInfo(brainDir, cancellationRel, "memory cancellation marker")
1003			if statErr != nil {
1004				return plan, statErr
1005			}
1006			if present {
1007				if err := addWork(cancellationRel); err != nil {
1008					return plan, err
1009				}
1010			}
1011		}
1012		if len(refSet) > brainstore.PrivacyTransactionSessionRefMax {
1013			return plan, fmt.Errorf("%s: privacy scope exceeds %d canonical session refs", brainstore.QueryTooBroadCode, brainstore.PrivacyTransactionSessionRefMax)
1014		}
1015		for ref := range refSet {
1016			plan.SessionRefs = append(plan.SessionRefs, ref)
1017		}
1018		sort.Strings(plan.SessionRefs)
1019		egressReceipts, egressErr := abstractEgressReceiptsForSessionRefsChecked(brainDir, refSet)
1020		if egressErr != nil {
1021			return plan, egressErr
1022		}
1023		for _, receipt := range egressReceipts {
1024			if err := addWork(receipt.Path); err != nil {
1025				return plan, err
1026			}
1027		}
1028		sort.Slice(plan.WorkMetadata, func(i, j int) bool { return plan.WorkMetadata[i].Path < plan.WorkMetadata[j].Path })
1029		return plan, nil
1030	}
1031	
1032	// privacyDerivedStoreRels is the static inventory of rebuildable derived
1033	// stores that exclude/purge delete wholesale and `privacy verify` re-checks;
1034	// dry-run, execution, and verification must never disagree on this list.
1035	func privacyDerivedStoreRels() []string {
1036		rels := []string{
1037			historyFTSDBRelPath(),
1038			filepath.ToSlash(filepath.Join(brainstore.HistoryDirName, historyScanCacheFileName)),
1039			historyShortTermPath,
1040			filepath.ToSlash(filepath.Join(brainstore.HistoryDirName, embedStoreDirName, historyVecStoreFileNamePortable)),
1041			filepath.ToSlash(filepath.Join(brainstore.HistoryDirName, embedStoreDirName, conversationVecStoreFileNamePortable)),
1042			patternsTasksPath,
1043			patterncore.ProceduresPath,
1044			patterncore.PracticesPath,
1045			patterncore.RunsRelPath,
1046		}
1047		rels = append(rels, patterncore.CorpusPrivacyArtifactRels()...)
1048		rels = append(rels, patterncore.CorpusPublicationMarkerPath)
1049		return rels
1050	}
1051	
1052	// privacyDerivedStoreArtifacts expands the static inventory with the
1053	// per-branch fact embedding caches (embeddings of distilled fact text; a
1054	// purged session's facts may be partially recoverable from them) and the
1055	// SQLite WAL/SHM siblings of every ordinary store and the publication layer's
