361			}
362			concepts, _ := truncateUTF8Bytes(strings.Join(result.Concepts, " | "), 3*1024)
363			fmt.Fprintf(out, "    proof concepts=%s worst_rank=%d rank_sum=%d approximate=%t\n", concepts, result.WorstRank, result.RankSum, result.Approximate)
364			for _, match := range result.ConceptMatches {
