426	func boundedSingleRepoRetrievalText(query string, results []unifiedResult, extras retrievalTransportExtras) ([]byte, error) {
427		extras = cloneRetrievalTransportExtras(extras)
428		extrasSteps := countRetrievalExtrasTrims(extras)
429		render := func(steps int) []byte {
430			ex := cloneRetrievalTransportExtras(extras)
431			for i := 0; i < min(steps, extrasSteps); i++ {
432				trimRetrievalExtrasOnce(&ex)
433			}
434			count := len(results) - max(steps-extrasSteps, 0)
435			return renderSingleRepoRetrievalText(query, results[:count], ex, steps > 0)
436		}
437		if data := render(0); len(data) <= conversationConceptResponseMaxBytes {
438			return data, nil
439		}
440		steps, ok, err := smallestTrimStepsThatFit(extrasSteps+len(results), func(steps int) (int, error) {
441			return len(render(steps)), nil
442		})
443		if err != nil {
444			return nil, err
445		}
446		if !ok {
447			return nil, fmt.Errorf("retrieval text envelope exceeds %d bytes without any result rows", conversationConceptResponseMaxBytes)
448		}
449		return render(steps), nil
450	}
