558	func trimWorkspaceGroupsToCount(groups []workspaceRetrieveResult, keep int, truncated bool) []workspaceRetrieveResult {
559		out := make([]workspaceRetrieveResult, len(groups))
560		remaining := keep
561		lastGroup, lastRow := -1, -1
562		for i, group := range groups {
563			out[i] = group
564			count := min(remaining, len(group.Results))
565			out[i].Results = append([]unifiedResult(nil), group.Results[:count]...)
566			remaining -= count
567			if count > 0 {
568				lastGroup, lastRow = i, count-1
569			}
570			refs := map[string]bool{}
571			for _, result := range out[i].Results {
572				if result.SessionRef != "" {
573					refs[result.SessionRef] = true
574				}
575			}
576			previews := make([]sessionAbstractPreview, 0, len(group.AbstractPreviews))
577			for _, preview := range group.AbstractPreviews {
578				if refs[preview.SessionRef] {
579					previews = append(previews, preview)
580				}
581			}
582			out[i].AbstractPreviews = previews
583			out[i].AbstractPreviewsTruncated = group.AbstractPreviewsTruncated || len(previews) != len(group.AbstractPreviews)
584		}
585		if truncated && lastGroup >= 0 {
586			out[lastGroup].Results[lastRow].ResponseTruncated = true
587		}
588		return out
