601	// trimWorkspaceExtrasOnce drops one lowest-priority optional tail item so the
602	// caller keeps a useful bounded response. A member's Error is deliberately NOT
603	// trimmable: clearing it makes a member whose retrieval failed serialize as
604	// {"results": []}, byte-identical to a healthy member with no matches, and the
605	// generic response_truncated marker does not say a failure was suppressed.
606	// Ranked rows are the cheap thing to drop; a member's failure is not.
607	func trimWorkspaceExtrasOnce(groups []workspaceRetrieveResult) bool {
608		for i := len(groups) - 1; i >= 0; i-- {
609			switch {
610			case len(groups[i].AbstractPreviews) > 0:
611				groups[i].AbstractPreviews = groups[i].AbstractPreviews[:len(groups[i].AbstractPreviews)-1]
612				groups[i].AbstractPreviewsTruncated = true
613				return true
614			case groups[i].Freshness.Detail != "":
615				groups[i].Freshness.Detail = ""
616				return true
617			case groups[i].Freshness.ContractDetail != "":
618				groups[i].Freshness.ContractDetail = ""
619				return true
620			}
621		}
622		return false
623	}
