636	// applyWorkspaceTrimSteps rebuilds the trim state after `steps` steps of the
637	// deterministic sequence shared by both workspace surfaces: optional extras
638	// first, then one kept row at a time, then whole tail groups.
639	func applyWorkspaceTrimSteps(pristine []workspaceRetrieveResult, extrasSteps, total, steps int) (groups []workspaceRetrieveResult, keep int) {
640		gs := cloneWorkspaceRetrieveGroups(pristine)
641		for i := 0; i < min(steps, extrasSteps); i++ {
642			trimWorkspaceExtrasOnce(gs)
643		}
644		rowDrops := min(max(steps-extrasSteps, 0), total)
645		groupDrops := max(steps-extrasSteps-total, 0)
646		return gs[:len(gs)-groupDrops], total - rowDrops
647	}
