651		total := 0
652		for _, group := range qualified {
653			total += len(group.Results)
654		}
655		extrasSteps := countWorkspaceExtrasTrims(qualified)
656		build := func(steps int) map[string]any {
657			gs, keep := applyWorkspaceTrimSteps(qualified, extrasSteps, total, steps)
658			payload := map[string]any{
659				"workspace": workspaceName,
660				"query":     query,
661				"results":   trimWorkspaceGroupsToCount(gs, keep, steps > 0),
662			}
663			if steps > 0 {
664				payload["response_truncated"] = true
665			}
