677		} else if size <= conversationConceptResponseMaxBytes {
678			return build(0), nil
679		}
680		steps, ok, err := smallestTrimStepsThatFit(extrasSteps+total+len(qualified), sizeAt)
681		if err != nil {
682			return nil, err
683		}
684		if !ok {
685			return nil, fmt.Errorf("workspace retrieval response envelope exceeds %d bytes without any result rows", conversationConceptResponseMaxBytes)
686		}
687		return build(steps), nil
688	}
