func runWorkspaceSkillsForm(ctx context.Context, cmd *cobra.Command, opts Options, name string, s skillFormOptions) error {
	manifest, err := workspace.DefaultStore(opts.Env).LoadManifest(name)
	if err != nil {
		return err
	}
	privacyPolicies, err := captureWorkspaceDerivedReadPolicies(opts.Env, manifest)
	if err != nil {
		return err
	}
	wsDir, err := workspace.DefaultStore(opts.Env).Dir(name)
	if err != nil {
		return err
	}
	if err := patterncore.ValidateCorpusReadSafety(wsDir); err != nil {
		return err
	}
	agent := s.agent
	if agent == "" || agent == "auto" {
		agent = defaultRefreshAgent(ctx, opts.Runner, ".")
	}
	if agent == "none" {
		return fmt.Errorf("skill synthesis requires an agent (codex or claude-code); none found on PATH")
	}
	return runPrivacyLinearizedPatternMutation(cmd, privacyPolicies, func() error {
		// Resolve the accepted source only after every member policy/lock is
		// pinned. Workspace verification uses the same locks, so a concurrent
		// family replacement cannot leave synthesis using a stale dossier.
		fam, ok, err := patterncore.AcceptedFamilyByIDChecked(wsDir, s.taskID)
		if err != nil {
			return err
		}
		if !ok {
			return fmt.Errorf("no accepted workspace family %q: run `"+clibase.BrainInvocation(os.LookupEnv, "workspace patterns verify")+" %s` (explicit, egress-gated), then `"+clibase.BrainInvocation(os.LookupEnv, "workspace patterns skills")+" %s`", s.taskID, name, name)
		}
		// A synthetic candidate carries id/name/scope + per-repo breakdown for
		// the skill-memory record; synthesis itself runs from the family.
		breakdown := make([]patternRepoStat, 0, len(fam.PerRepo))
		for _, v := range fam.PerRepo {
			breakdown = append(breakdown, patternRepoStat{RepoKey: v.RepoKey, Support: 1})
		}
		cand := taskCandidate{
			ID: fam.ID, Label: fam.Title, Workspace: name, Repos: fam.RepoCount(),
			RepoBreakdown: breakdown, Commands: fam.CommonWorkflow, Support: fam.RepoCount(),
			Strength: 0.7, StrengthLabel: "high",
		}
		return synthesizeAndForm(ctx, cmd, cand, nil, &fam, wsDir, ".", agent, defaultDistillAgentRunner(agent), s, opts.Now().UTC())
	})
}

// the WORKSPACE brain before any derived-read gate runs.
//
// Every workspace entry point gates on CaptureWorkspaceDerivedReadPolicies,
// which fails closed while the publication marker survives ("run a locked
// pattern refresh to recover"). Recovery is what removes that marker, so if it
// only ran inside the gated build, refresh would be blocked by the very state
// it exists to repair and the workspace corpus would be permanently stuck. The
// repo path gets this ordering for free: buildPatternCorpusLocked recovers
// first, under the brain write lock, with no gate ahead of it. Read-only
// workspace commands deliberately keep failing closed; only the repair path is
// allowed through.
func RecoverWorkspaceCorpusPublication(env base.EntireEnv, manifest workspace.Manifest) error {
	wsBrainDir, err := workspace.DefaultStore(env).Dir(manifest.Name)
	if err != nil {
		return err
	}
	return brainstore.WithBrainWriteLock(wsBrainDir, func() error {
		return RecoverCorpusPublicationLocked(wsBrainDir, DecodeCorpusPublication)
	})
}

// BuildWorkspaceCorpus rebuilds the workspace corpus from member corpora.
func BuildWorkspaceCorpus(env base.EntireEnv, manifest workspace.Manifest, verify VerifyDerivedClean, now time.Time) (WorkspaceCorpusCounts, error) {
	if err := RecoverWorkspaceCorpusPublication(env, manifest); err != nil {
		return WorkspaceCorpusCounts{}, err
	}
	policies, err := CaptureWorkspaceDerivedReadPolicies(env, manifest, verify)
	if err != nil {
		return WorkspaceCorpusCounts{}, err
	}
	var counts WorkspaceCorpusCounts
	err = brainstore.WithLockedRetrievalPrivacyPolicies(policies, func(brainDir string) error {
		return RequireDerivedRead(brainDir, verify)
	}, func() error {
		var buildErr error
		counts, buildErr = BuildWorkspaceCorpusLocked(env, manifest, now)
		return buildErr
	})
	return counts, err
}

func BuildWorkspaceCorpusLocked(env base.EntireEnv, manifest workspace.Manifest, now time.Time) (WorkspaceCorpusCounts, error) {
	var counts WorkspaceCorpusCounts
	wsBrainDir, err := workspace.DefaultStore(env).Dir(manifest.Name)
	if err != nil {
		return counts, err
	}
	if err := RecoverCorpusPublicationLocked(wsBrainDir, DecodeCorpusPublication); err != nil {
		return counts, err
	}
	path, cleanup, err := PrepareCorpusStaging(wsBrainDir)
	if err != nil {
		return counts, err
	}
	defer cleanup()
	db, err := sql.Open(sqlitedriver.Name, path)
	if err != nil {
		return counts, err
	}
	defer db.Close()
	for _, p := range []string{"PRAGMA busy_timeout=5000", "PRAGMA foreign_keys=ON"} {
		if _, err := db.Exec(p); err != nil {
			return counts, err
		}
	}
	for _, stmt := range CorpusSchema {
		if _, err := db.Exec(stmt); err != nil {
			return counts, err
		}
	}

	repos := append([]workspace.Repo(nil), manifest.Repos...)
	sort.Slice(repos, func(i, j int) bool { return repos[i].RepoKey < repos[j].RepoKey })
	counts.Members = len(repos)

