82			location, snapshot, err := store.lookupLocation(ctx, file.Rel)
83			if err != nil {
84				if backed {
85					retain(file.Rel, "checkpoint copy is unavailable")
86					continue
87				}
88				return nil, fmt.Errorf("retain transcript cache: %w", err)
89			}
90			data, err := readSnapshotTranscriptFromSource(ctx, runner, snapshot, location.sourceKey, location.sourcePath)
91			if err != nil {
92				if backed {
93					retain(file.Rel, "checkpoint copy is unreadable")
94					continue
95				}
96				return nil, fmt.Errorf("retain transcript cache for %s: %w", file.Rel, err)
97			}
98			cached, _, err := readHistorySessionInventoryFile(ctx, inventory, file)
99			if err != nil {
100				return nil, err
101			}
102			switch {
103			case bytes.HasPrefix(data, cached):
104				// The checkpoint holds every cached byte (equal, or the
105				// append-only transcript ran ahead of the last disk export), so
106				// the file is recoverable and safe to sweep.
107			case bytes.HasPrefix(cached, data):
108				// The disk export ran ahead of the last checkpoint. Keep the
109				// file out of the sweep instead of blocking every future export;
110				// a later checkpoint reconciles it and the next sweep collects
111				// it. Checkpoint-backed exports repeat this proof so the file is
112				// never deleted while it still holds the only copy of the tail.
113				retain(file.Rel, "cached transcript is newer than its checkpoint")
114			case backed:
115				// A divergent override of a checkpoint-backed session is an
116				// untrusted stray; sweeping it is the established cleanup.
117			default:
118				// Divergent, and nothing proves which copy is whole: neither is a
119				// prefix of the other, and this brain is not checkpoint-backed, so
120				// the cached file may hold bytes the checkpoint never saw.
121				//
122				// This used to return an error, which aborted the WHOLE delta
123				// export over one stray file -- and never self-healed, because
124				// nothing in the export path reconciles a divergence. Observed:
125				// one session file froze a real brain's manifest at 2026-10-11 for
126				// thirteen days, and because the source never advanced, the memory
127				// worker's receipt digest never matched its job digest, so it
128				// failed `memory_source_stale` and relaunched on backoff forever.
129				// Every symptom was two layers away from this line.
130				//
131				// Retaining is both safer and unblocking: the file is kept either
132				// way (the error path deleted nothing), so refusing to sweep it
133				// loses no bytes, while the export goes on and every other session
134				// gets through. It is exactly what the newer-than-its-checkpoint
135				// case above already does, for the reason stated there -- "instead
136				// of blocking every future export".
137				retain(file.Rel, "checkpoint bytes differ")
138			}
139		}
140		if len(retained) > 0 {
141			kept := inventory.files[:0]
142			for _, file := range inventory.files {
143				if !retained[file.Rel] {
144					kept = append(kept, file)
145				}
146			}
147			inventory.files = kept
148		}
149		success = true
150		return inventory, nil
151	}
