153	// sweepTranscriptCache removes only the descriptor-bound files validated by the
154	// migration preflight. The caller holds the brain write lock and has published
155	// the checkpoint-backed manifest. Directories are removed only when empty.
156	func sweepTranscriptCache(ctx context.Context, inventory *historySessionInventory) error {
157		if inventory == nil {
158			return nil
159		}
160		current, err := collectHistorySessionInventoryMode(ctx, inventory.brainDir, true)
161		if err != nil {
162			return err
163		}
164		unchanged := inventory.sameMembership(current)
165		_ = current.Close()
166		if !unchanged {
167			return fmt.Errorf("%s: transcript cache changed before migration sweep", brainstore.SourceStaleCode)
168		}
169		if err := inventory.validateAll(ctx); err != nil {
170			return err
171		}
172		for _, file := range inventory.files {
173			if err := inventory.validateFileMembership(ctx, file); err != nil {
174				return err
175			}
176			if err := inventory.root.Remove(file.Rel); err != nil {
177				return err
178			}
179		}
180		for i := len(inventory.entries) - 1; i >= 0; i-- {
181			if inventory.entries[i].Mode.IsDir() {
182				// A nonempty directory may contain non-transcript artifacts.
183				_ = inventory.root.Remove(inventory.entries[i].Rel)
184			}
185		}
186		if len(inventory.files) > 0 {
187			fmt.Fprintf(os.Stderr, "transcript cache: removed %d cached transcript file(s); originals remain recoverable from checkpoints\n", len(inventory.files))
188		}
189		return nil
190	}
