	}
	missing := map[string]bool{}
	for _, file := range files {
		if !liveRefs[file.Receipt.SessionRef] {
			missing[file.Receipt.SessionRef] = true
		}
	}
	if len(missing) == 0 {
		return 0, nil
	}
	return len(missing), purgeAbstractEgressReceiptsForSessionRefs(brainDir, missing)
}

